const int redPin = 9;
const int greenPin = 10;
const int bluePin = 11;

void setRgb(int r, int g, int b) {
  analogWrite(redPin, r);
  analogWrite(greenPin, g);
  analogWrite(bluePin, b);
}

void setup() {
  pinMode(redPin, OUTPUT);
  pinMode(greenPin, OUTPUT);
  pinMode(bluePin, OUTPUT);
}

void loop() {
  // Red to Yellow
  for (int g = 0; g <= 255; g++) {
    setRgb(255, g, 0);
    delay(10);
  }
  // Yellow to Green
  for (int r = 255; r >= 0; r--) {
    setRgb(r, 255, 0);
    delay(10);
  }
  // Green to Cyan
  for (int b = 0; b <= 255; b++) {
    setRgb(0, 255, b);
    delay(10);
  }
  // Cyan to Blue
  for (int g = 255; g >= 0; g--) {
    setRgb(0, g, 255);
    delay(10);
  }
  // Blue to Magenta
  for (int r = 0; r <= 255; r++) {
    setRgb(r, 0, 255);
    delay(10);
  }
  // Magenta to Red
  for (int b = 255; b >= 0; b--) {
    setRgb(255, 0, b);
    delay(10);
  }
}

